class TestSkillInstanceConcurrency:
    """Thread-safety and concurrent access patterns."""

    def test_concurrent_state_updates(self):
        """Concurrent state updates maintain consistency."""
        import threading
        inst = SkillInstance(skill_name="test")
        errors = []

        def update_state():
            try:
                inst.state = SkillState.ACTIVE
                inst.state = SkillState.EXECUTING
                inst.state = SkillState.TERMINATED
            except Exception as e:  # pragma: no cover
                errors.append(e)

        threads = [threading.Thread(target=update_state) for _ in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert not errors, f"Concurrent updates failed: {errors}"
        assert inst.state == SkillState.TERMINATED

    def test_concurrent_reads(self):
        """Concurrent reads are safe."""
        import threading
        inst = SkillInstance(skill_name="test", state=SkillState.ACTIVE)
        results = []

        def read_state():
            results.append(inst.state)

        threads = [threading.Thread(target=read_state) for _ in range(50)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert all(r == SkillState.ACTIVE for r in results)


